-- Script in ServerScriptService
local MarketplaceService = game:GetService("MarketplaceService")
local Players = game:GetService("Players")
local HAT_ID = 1029025 -- an example asset id

Players.PlayerAdded:Connect(function(player)
	local ok, owns = pcall(function()
		return MarketplaceService:PlayerOwnsAssetAsync(player, HAT_ID)
	end)
	print(player.Name, "owns hat:", ok and owns)
end)

-- Script in ServerScriptService
local MessagingService = game:GetService("MessagingService")

local ok, connection = pcall(function()
	return MessagingService:SubscribeAsync("StartEvent", function(message)
		print("Event starting:", message.Data.name)
	end)
end)

